{"path": "packages/gateway/src/server.ts", "start_line": 1, "end_line": 371, "total_lines": 371, "content": "     1	/**
     2	 * A thin HTTP entrypoint for the Metered Web Broker — one endpoint, one contract.
     3	 *
     4	 * The `Broker` is a library (see `packages/gateway/src/broker.ts`); nothing in
     5	 * the repo previously bound a socket. This file is the only "web" layer: it
     6	 * wires a `Broker` from environment config, serves `GET /health` and `GET /`,
     7	 * mounts the metered `POST /fetch`, and exposes the audit ledger at `GET /audit`.
     8	 *
     9	 * It uses Node's built-in `http` module (no Express) so the production image is
    10	 * small and cold-start cheap — one Node process, no PaaS, exactly what the VPS
    11	 * deploy targets. The broker's orchestration is reused untouched.
    12	 *
    13	 *   # run it (TS directly)
    14	 *   npx tsx packages/gateway/src/server.ts
    15	 *   # or, in the image
    16	 *   npm start
    17	 *
    18	 *   curl -s localhost:8787/health
    19	 *   curl -s localhost:8787/fetch -XPOST -H'content-type: application/json' \
    20	 *       -d '{"url":"https://api.example.com/wire/42"}'
    21	 *   curl -s localhost:8787/audit
    22	 */
    23	
    24	import {
    25	  createServer,
    26	  type IncomingMessage,
    27	  type Server,
    28	  type ServerResponse,
    29	} from 'node:http';
    30	import { Broker } from './broker.js';
    31	import { BudgetEngine, defaultPolicy, type BudgetPolicy } from '@mwb/budget';
    32	import { AuditLedger, reconcile, renderDashboard, summarize } from '@mwb/audit';
    33	import { KeyRing } from '@mwb/identity';
    34	import { InMemoryRail } from '@mwb/rails';
    35	import {
    36	  systemClock,
    37	  url as brandUrl,
    38	  type Clock,
    39	  type HeaderRecord,
    40	  type PaymentRail,
    41	  type PaymentRequest,
    42	  type UrlString,
    43	} from '@mwb/core';
    44	import type { OriginClient, OriginResponse } from './broker.js';
    45	
    46	/** The port the HTTP server binds. Defaults to 8787 for a small VPS. */
    47	export const PORT = Number(process.env.PORT ?? 8787);
    48	
    49	/** Host/interface to bind. Default: all interfaces (Caddy fronts it in prod). */
    50	export const HOST = process.env.HOST ?? '0.0.0.0';
    51	
    52	/**
    53	 * A metered origin client. Two modes:
    54	 *
    55	 *  - `ORIGIN_URL` unset (default): a self-fulfilling origin. Every settled
    56	 *    request returns HTTP 200 with synthetic body + no license. This lets the
    57	 *    broker run `fulfilled` end-to-end with no real origin behind it — the
    58	 *    whole metered path (quote → authorize → settle → record) executes.
    59	 *  - `ORIGIN_URL` set: the settled request is proxied to that URL over HTTP.
    60	 *    This is the path to a real metered origin (self 402, x402, Cloudflare PPC).
    61	 */
    62	export class MeteredOrigin implements OriginClient {
    63	  private readonly target?: UrlString;
    64	
    65	  constructor(target?: UrlString) {
    66	    this.target = target;
    67	  }
    68	
    69	  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    70	    if (this.target) {
    71	      const res = await fetch(this.target, {
    72	        method: req.method,
    73	        headers: req.headers,
    74	      });
    75	      return {
    76	        httpStatus: res.status,
    77	        headers: headerRecord(res),
    78	        body: await res.text(),
    79	      };
    80	    }
    81	    // Self origin: nothing behind the broker, so report satisfied.
    82	    return {
    83	      httpStatus: 200,
    84	      headers: { 'content-type': 'text/plain; charset=utf-8' },
    85	      body: 'metered content from a self-hosted origin (ORIGIN_URL unset)',
    86	    };
    87	  }
    88	}
    89	
    90	/** Build the Rail from env. Today: InMemoryRail (the self 402-style backend). */
    91	export function buildRail(clock: Clock): PaymentRail {
    92	  const id = process.env.RAIL_ID ?? 'self402';
    93	  // A price of 5000 micros (0.005) is comfortably under the per-call ceiling
    94	  // (10_000) so the default self-origin fetch reaches the fulfilled terminal.
    95	  const priceMicros = Number(
    96	    process.env.RAIL_PRICE_MICROS ?? 5000,
    97	  );
    98	  return new InMemoryRail({
    99	    id,
   100	    priceMicros,
   101	    currency: defaultPolicy.currency,
   102	    clock,
   103	    settlementSeed: process.env.RAIL_SETTLEMENT_SEED ?? 'self',
   104	  });
   105	}
   106	
   107	/** Parse budget policy from env, overriding just the per-call ceiling. */
   108	function buildPolicy(): BudgetPolicy {
   109	  const policy: BudgetPolicy = { ...defaultPolicy };
   110	  const ceiling = process.env.PER_CALL_CEILING_MICROS;
   111	  if (ceiling && Number.isFinite(Number(ceiling))) {
   112	    policy.perCallCeilingMicros = Number(ceiling);
   113	  }
   114	  return policy;
   115	}
   116	
   117	/**
   118	 * Build the full broker from env. Every collaborator is injected exactly as the
   119	 * broker unit tests do, so the wiring here is the same one the test proves.
   120	 *
   121	 * Returns the broker alongside the small bits of state the HTTP layer needs to
   122	 * shape responses (the audit ledger, the origin mode, whether identity is on)
   123	 * so `createApp` never reaches into broker internals.
   124	 */
   125	export function buildBroker(): {
   126	  broker: Broker;
   127	  ledger: AuditLedger;
   128	  origin: MeteredOrigin;
   129	  originTarget?: UrlString;
   130	  identityOn: boolean;
   131	} {
   132	  const clock: Clock = systemClock;
   133	  const ledger = new AuditLedger({ clock });
   134	  const origin = new MeteredOrigin(process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined);
   135	  const ring = process.env.IDENTITY_KEY_ID ? new KeyRing(clock) : undefined;
   136	  const identityOn = ring !== undefined;
   137	  const broker = new Broker({
   138	    rail: buildRail(clock),
   139	    budget: new BudgetEngine({ clock, policy: buildPolicy() }),
   140	    ledger,
   141	    ring,
   142	    origin,
   143	    clock,
   144	    identity: identityOn
   145	      ? { subject: process.env.IDENTITY_SUBJECT }
   146	      : undefined,
   147	  });
   148	  return {
   149	    broker,
   150	    ledger,
   151	    origin,
   152	    originTarget: process.env.ORIGIN_URL ? brandUrl(process.env.ORIGIN_URL) : undefined,
   153	    identityOn,
   154	  };
   155	}
   156	
   157	/** Read the whole request body as text. */
   158	async function readBody(req: IncomingMessage): Promise<string> {
   159	  const chunks: Buffer[] = [];
   160	  for await (const chunk of req) chunks.push(chunk as Buffer);
   161	  return Buffer.concat(chunks).toString('utf-8');
   162	}
   163	
   164	/** A plain object from an HTTP response's headers (Node Headers → record). */
   165	function headerRecord(res: Response): HeaderRecord {
   166	  const out: HeaderRecord = {};
   167	  res.headers.forEach((v, k) => {
   168	    out[k] = v;
   169	  });
   170	  return out;
   171	}
   172	
   173	/** Send a JSON response with status and Content-Type. */
   174	function sendJson(res: ServerResponse, status: number, body: unknown): void {
   175	  const raw = JSON.stringify(body);
   176	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
   177	  res.end(raw);
   178	}
   179	
   180	/** One metered request, decoded from the request body. */
   181	export interface FetchRequest {
   182	  /** The absolute URL of the metered content to fetch. */
   183	  url: UrlString;
   184	  /** Optional tenant/subject for multi-tenant accounting. */
   185	  tenantId?: string;
   186	  /**
   187	   * Optional `fetchId`. Absent ⇒ the broker derives one. Present ⇒ idempotent
   188	   * (a repeat id returns the cached outcome without re-charging the meter).
   189	   */
   190	  fetchId?: string;
   191	  /** Optional headers to present to the origin on the settled request. */
   192	  headers?: HeaderRecord;
   193	}
   194	
   195	/**
   196	 * Handle `POST /fetch`. Decodes the request, runs `Broker.fetch`, and maps the
   197	 * broker's terminal outcome to a JSON response. Every broker terminal class is
   198	 * one of {fulfilled, blocked, payment-required, token-rejected}; there is no
   199	 * generic `error` status.
   200	 */
   201	export async function handleFetch(
   202	  broker: Broker,
   203	  raw: string,
   204	): Promise<{ status: number; body: unknown }> {
   205	  let req: FetchRequest;
   206	  try {
   207	    req = JSON.parse(raw) as FetchRequest;
   208	  } catch {
   209	    return { status: 400, body: { error: 'invalid JSON body' } };
   210	  }
   211	  if (!req || typeof req.url !== 'string') {
   212	    return { status: 400, body: { error: "missing required string field 'url'" } };
   213	  }
   214	
   215	  const outcome = await broker.fetch({
   216	    url: req.url,
   217	    fetchId: req.fetchId,
   218	    tenantId: req.tenantId,
   219	    headers: req.headers as HeaderRecord | undefined,
   220	  });
   221	
   222	  // A fulfilled metered fetch succeeds (200). Otherwise map the terminal class
   223	  // to an HTTP status agents can branch on: payment-required (402) for any
   224	  // metered-charge gate, and 403 for the rest (blocked, token-rejected, error).
   225	  const status =
   226	    outcome.status === 'fulfilled'
   227	      ? 200
   228	      : outcome.failureClass === 'payment-required'
   229	        ? 402
   230	        : 403;
   231	  return { status, body: outcome };
   232	}
   233	
   234	/** Handle `GET /health` — liveness, no dependencies. */
   235	export function handleHealth(): { status: number; body: unknown } {
   236	  return { status: 200, body: { status: 'ok', clock: systemClock.now() } };
   237	}
   238	
   239	/** Handle `GET /audit` — JSON: the latest ledger rows. */
   240	export function handleAudit(ledger: AuditLedger): { status: number; body: unknown } {
   241	  const rows = ledger.toRows();
   242	  return { status: 200, body: { rows, summary: summarize(rows) } };
   243	}
   244	
   245	/** Handle `GET /audit/dashboard` — the reconciliation dashboard as text. */
   246	export function handleAuditDashboard(ledger: AuditLedger): {
   247	  status: number;
   248	  body: unknown;
   249	} {
   250	  const rows = ledger.toRows();
   251	  const dashboard = renderDashboard(rows, 'Metered Web Broker');
   252	  const recon = reconcile(rows);
   253	  return {
   254	    status: 200,
   255	    body: { dashboard, reconciliation: recon, count: rows.length },
   256	  };
   257	}
   258	
   259	/** Handle `GET /` — a small JSON index of the endpoints. */
   260	export function handleIndex(): { status: number; body: unknown } {
   261	  return {
   262	    status: 200,
   263	    body: {
   264	      service: 'metered-web-broker',
   265	      endpoints: {
   266	        'GET /': 'this index',
   267	        'GET /health': 'liveness',
   268	        'POST /fetch': '{"url", fetchId?, tenantId?}',
   269	        'GET /audit': 'latest ledger rows + summary',
   270	        'GET /audit/dashboard': 'reconciliation dashboard',
   271	      },
   272	    },
   273	  };
   274	}
   275	
   276	/**
   277	 * Create (but do not start) the HTTP server. Exposed so the test can bind an
   278	 * ephemeral port without opening a real socket in the module.
   279	 */
   280	export interface ServerConfig {
   281	  broker: Broker;
   282	  ledger: AuditLedger;
   283	  origin: MeteredOrigin;
   284	  /** The proxied-origin URL, if ORIGIN_URL was set; else undefined (self origin). */
   285	  originTarget?: UrlString;
   286	}
   287	
   288	/**
   289	 * Create (but do not start) the HTTP server. Exposed so the test can bind an
   290	 * ephemeral port without opening a real socket in the module.
   291	 */
   292	export function createApp(cfg: ServerConfig): Server {
   293	  const { ledger, origin, originTarget, broker } = cfg;
   294	
   295	  const server = createServer((req, res) => {
   296	    const url = req.url ?? '/';
   297	    const method = req.method ?? 'GET';
   298	
   299	    if (method === 'GET' && url === '/health') {
   300	      const { status, body } = handleHealth();
   301	      return void sendJson(res, status, body);
   302	    }
   303	    if (method === 'GET' && url === '/') {
   304	      const { status, body } = handleIndex();
   305	      return void sendJson(res, status, body);
   306	    }
   307	    if (method === 'GET' && url === '/audit/dashboard') {
   308	      const { status, body } = handleAuditDashboard(ledger);
   309	      return void sendJson(res, status, body);
   310	    }
   311	    if (method === 'GET' && url === '/audit') {
   312	      const { status, body } = handleAudit(ledger);
   313	      return void sendJson(res, status, body);
   314	    }
   315	    if (method === 'POST' && url === '/fetch') {
   316	      void (async () => {
   317	        try {
   318	          const raw = await readBody(req);
   319	          const { status, body } = await handleFetch(broker, raw);
   320	          return void sendJson(res, status, body);
   321	        } catch (err) {
   322	          const message = err instanceof Error ? err.message : String(err);
   323	          // A failure *inside* the server (not the metered path) is a 500; the
   324	          // metered path never produces a generic error status.
   325	          return void sendJson(res, 500, { error: 'server error', message });
   326	        }
   327	      })();
   328	      return;
   329	    }
   330	
   331	    // Unknown route.
   332	    const { status, body } = {
   333	      status: 404,
   334	      body: {
   335	        error: 'not found',
   336	        path: url,
   337	        endpoints: ['/', '/health', '/fetch', '/audit', '/audit/dashboard'],
   338	      },
   339	    };
   340	    return void sendJson(res, status, body);
   341	  });
   342	
   343	  // Log the effective origin mode (self-origin or proxied) at boot.
