    63	    opts.ring = r;
    64	    // A known subject is what makes the broker issue a PACT, so the
    65	    // fulfilled outcome carries a pactToken (not just a keyId).
    66	    opts.identity = { subject: 'tenant:test-key' };
    67	  }
    68	  return { budget, ledger, rail, opts };
    69	}
    70	
    71	function run(opts: ConstructorParameters<typeof Broker>[0], params?: { fetchId?: string; tenantId?: string }) {
    72	  const b = new Broker(opts);
