{"path": "packages/budget/src/engine.ts", "start_line": 1, "end_line": 230, "total_lines": 230, "content": "     1	import { BudgetError, type Clock, type Micros, type Price, type UrlString } from '@mwb/core';
     2	import {
     3	  defaultPolicy,
     4	  matchLineItem,
     5	  type BudgetPolicy,
     6	} from './policy.js';
     7	
     8	/**
     9	 * A meter is the accounting state for a tenant's spend.
    10	 *
    11	 * Buckets:
    12	 *  - per-call  : one-shot check, not persistent here.
    13	 *  - hourly    : rolling 1-hour window for the tenant.
    14	 *  - daily     : rolling 24-hour window for the tenant.
    15	 *  - line-item : per-line-item buckets (daily + lifetime).
    16	 *
    17	 * The engine does not persist by itself. `AuditLedger` (or a durable
    18	 * implementation) persists records and rehydrates buckets if needed.
    19	 */
    20	export interface MeterState {
    21	  tenantId: string;
    22	  hourly: { windowStart: number; spentMicros: Micros };
    23	  daily: { windowStart: number; spentMicros: Micros };
    24	  lineItems: Record<string, { dailyMicros: number; lifetimeMicros: number }>;
    25	}
    26	
    27	export function emptyMeter(tenantId: string, clock: Clock): MeterState {
    28	  return {
    29	    tenantId,
    30	    hourly: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    31	    daily: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    32	    lineItems: {},
    33	  };
    34	}
    35	
    36	interface CheckResult {
    37	  ok: boolean;
    38	  code: string;
    39	  reason: string;
    40	  remainingMicros?: number;
    41	}
    42	
    43	function checkBucket(
    44	  bucketMicros: number,
    45	  ceilingMicros: number,
    46	  priceMicros: number,
    47	  label: string
    48	): CheckResult {
    49	  const remaining = ceilingMicros - bucketMicros;
    50	  if (remaining < 0) return { ok: false, code: 'CEILING_EXCEEDED', reason: `${label}: already over ceiling` };
    51	  if (priceMicros >= remaining) {
    52	    return {
    53	      ok: false,
    54	      code: 'PRICE_EXCEEDS_REMAINING',
    55	      reason: `${label}: requested ${priceMicros} exceeds remaining ${remaining}`,
    56	      remainingMicros: remaining,
    57	    };
    58	  }
    59	  return { ok: true, code: 'OK', reason: '', remainingMicros: remaining };
    60	}
    61	
    62	function advanceWindow(
    63	  bucket: { windowStart: number; spentMicros: number },
    64	  nowMs: number,
    65	  windowMs: number
    66	): { windowStart: number; spentMicros: number } {
    67	  if (nowMs - bucket.windowStart >= windowMs) return { windowStart: nowMs, spentMicros: 0 };
    68	  return bucket;
    69	}
    70	
    71	const HOUR_MS = 3_600_000;
    72	const DAY_MS = 86_400_000;
    73	/**
    74	 * The Budget Engine.
    75	 *
    76	 * Responsibilities (and only responsibilities):
    77	 *  1. Refuse work that cannot fit inside a declared ceiling.
    78	 *  2. Record work that has been done (paid or denied) into the meter.
    79	 *  3. Tell the caller exactly which ceiling bit and why.
    80	 *
    81	 * It does NOT decide what to pay with, it does NOT sign anything, it
    82	 * does NOT enforce licenses. Those are the Rail Adapter, Identity, and
    83	 * License Engine. Keeping them separate is what makes each one swappable —
    84	 * which is the whole point of "one contract."
    85	 */
    86	export class BudgetEngine {
    87	  private readonly meters = new Map<string, MeterState>();
    88	  private readonly clock: Clock;
    89	  private readonly _policy: BudgetPolicy;
    90	
    91	  constructor(options?: { clock?: Clock; policy?: BudgetPolicy }) {
    92	    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
    93	    this._policy = options?.policy ?? defaultPolicy;
    94	  }
    95	
    96	  get policy(): BudgetPolicy {
    97	    return this._policy;
    98	  }
    99	
   100	  /**
   101	   * Pre-flight: will this request fit?
   102	   *
   103	   * This is the ONLY pre-payment step that may raise BudgetError. The
   104	   * broker surfaces it as `failureClass: 'blocked'` — a policy denial —
   105	   * which the audit layer records as a `denied` row.
   106	   *
   107	   * Deliberately throws (not returns a decision object) because "does not
   108	   * fit" is an exceptional condition for the caller and the audit trail
   109	   * cares about the message, not a tagged union.
   110	   */
   111	  preflight(tenantId: string, price: Price, url?: UrlString): void {
   112	    if (price.currency !== this._policy.currency) {
   113	      throw new BudgetError(
   114	        `Tenant currency mismatch: policy is ${this._policy.currency}, quote is ${price.currency}`,
   115	        'CURRENCY_MISMATCH'
   116	      );
   117	    }
   118	    if (!Number.isSafeInteger(price.unitsMicros) || price.unitsMicros <= 0) {
   119	      throw new BudgetError(`Quote must be a positive safe integer, got ${price.unitsMicros}`, 'BAD_QUOTE');
   120	    }
   121	    if (price.unitsMicros > this._policy.perCallCeilingMicros) {
   122	      throw new BudgetError(
   123	        `Per-call ceiling exceeded: quote ${price.unitsMicros} > ${this._policy.perCallCeilingMicros}`,
   124	        'PER_CALL_CEILING'
   125	      );
   126	    }
   127	
   128	    const nowMs = Date.parse(this.clock.now());
   129	    const state = this.getOrCreate(tenantId, nowMs);
   130	
   131	    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
   132	    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);
   133	
   134	    const hourlyCheck = checkBucket(
   135	      state.hourly.spentMicros,
   136	      this._policy.hourlyTenantCeilingMicros,
   137	      price.unitsMicros,
   138	      `hourly tenant ceiling`
   139	    );
   140	    if (!hourlyCheck.ok) throw new BudgetError(hourlyCheck.reason, hourlyCheck.code);
   141	
   142	    const dailyCheck = checkBucket(
   143	      state.daily.spentMicros,
   144	      this._policy.dailyTenantCeilingMicros,
   145	      price.unitsMicros,
   146	      `daily tenant ceiling`
   147	    );
   148	    if (!dailyCheck.ok) throw new BudgetError(dailyCheck.reason, dailyCheck.code);
   149	
   150	    if (url) {
   151	      const li = matchLineItem(this._policy, url);
   152	      if (li) {
   153	        if (price.currency !== li.currency) {
   154	          throw new BudgetError(
   155	            `Line-item currency mismatch: ${li.currency} vs quote ${price.currency}`,
   156	            'LINE_ITEM_CURRENCY'
   157	          );
   158	        }
   159	        const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
   160	        const dCheck = checkBucket(
   161	          bucket.dailyMicros,
   162	          li.dailyCeilingMicros,
   163	          price.unitsMicros,
   164	          `line-item daily (${li.match})`
   165	        );
   166	        if (!dCheck.ok) throw new BudgetError(dCheck.reason, dCheck.code);
   167	        const lCheck = checkBucket(
   168	          bucket.lifetimeMicros,
   169	          li.lifetimeCeilingMicros,
   170	          price.unitsMicros,
   171	          `line-item lifetime (${li.match})`
   172	        );
   173	        if (!lCheck.ok) throw new BudgetError(lCheck.reason, lCheck.code);
   174	      }
   175	    }
   176	  }
   177	
   178	  /**
   179	   * Record a completed paid fetch. Advances every meter that was charged
   180	   * for this call. The broker calls this exactly once per settled fetch.
   181	   */
   182	  recordPaid(tenantId: string, price: Price, url: UrlString): void {
   183	    const nowMs = Date.parse(this.clock.now());
   184	    const state = this.getOrCreate(tenantId, nowMs);
   185	    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
   186	    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);
   187	    state.hourly.spentMicros += price.unitsMicros;
   188	    state.daily.spentMicros += price.unitsMicros;
   189	
   190	    const li = matchLineItem(this._policy, url);
   191	    if (li) {
   192	      const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
   193	      bucket.dailyMicros += price.unitsMicros;
   194	      bucket.lifetimeMicros += price.unitsMicros;
   195	      state.lineItems[li.match] = bucket;
   196	    }
   197	  }
   198	
   199	  /**
   200	   * Record a denied fetch. Does NOT charge, but SHOULD be observed on
   201	   * dashboards to distinguish "the agent tried and was stopped by us" from
   202	   * "the agent tried and was stopped by the origin."
   203	   *
   204	   * Denial rows live in the audit ledger; this hook is kept so a future
   205	   * in-memory rate limiter (e.g. deny-burst) can subscribe uniformly.
   206	   */
   207	  recordDenied(_tenantId: string): void {
   208	    // Intentionally no-op in-memory; the audit ledger is the source of truth.
   209	  }
   210	
   211	  /** Snapshot of current meter state for the dashboard. */
   212	  snapshot(tenantId: string): MeterState {
   213	    const state = this.meters.get(tenantId);
   214	    if (!state) throw new BudgetError(`Unknown tenant: ${tenantId}`, 'UNKNOWN_TENANT');
   215	    return structuredClone(state);
   216	  }
   217	
   218	  private getOrCreate(tenantId: string, nowMs: number): MeterState {
   219	    let state = this.meters.get(tenantId);
   220	    if (!state) {
   221	      state = emptyMeter(tenantId, { now: () => new Date(nowMs).toISOString() });
   222	      this.meters.set(tenantId, state);
   223	    }
   224	    return state;
   225	  }
   226	}
   227	
   228	// Re-export so imports don't need to reach into the policy module.
   229	export { defaultPolicy, matchLineItem, globMatch } from './policy.js';
   230	export type { BudgetPolicy, LineItem } from './policy.js';"}

{"path": "packages/budget/src/policy.ts", "start_line": 1, "end_line": 101, "total_lines": 101, "content": "     1	import type { FailureClass, Price, UrlString } from '@mwb/core';
     2	
     3	/**
     4	 * Budget decision returned by the BudgetEngine before the broker does any
     5	 * network work, or after it observes the origin's response.
     6	 *
     7	 * The point: a "generic failure" is no longer reportable. Every terminal
     8	 * state maps to one of the three classes so an agent (or a human dashboard)
     9	 * can say exactly why the cost decision happened.
    10	 */
    11	export type PreFlightDecision =
    12	  | {
    13	      kind: 'allow';
    14	      /** The price quote the engine will pay without further action. */
    15	      quote: Price;
    16	      /** Rail the quote came from; the broker pays through this rail. */
    17	      rail: string;
    18	      note?: string;
    19	    }
    20	  | {
    21	      kind: 'require-settlement';
    22	      /** Quote that needs an explicit settlement authorization. */
    23	      quote: Price;
    24	      rail: string;
    25	      reason: string;
    26	    }
    27	  | {
    28	      kind: 'deny';
    29	      failureClass: Extract<FailureClass, 'blocked' | 'token-rejected'>;
    30	      code: string;
    31	      reason: string;
    32	    };
    33	
    34	export type OutcomeDecision =
    35	  | { kind: 'record-paid'; failureClass?: never }
    36	  | { kind: 'record-denied'; failureClass: FailureClass; code?: string; reason: string };
    37	
    38	/**
    39	 * A line-item: the recurring ceiling that groups URLs (e.g. all fetches to
    40	 * news-site.com, or a domain group). Treated like a monthly credit line.
    41	 */
    42	export interface LineItem {
    43	  /** Glob over host + path. Supports `*` anywhere. */
    44	  match: string;
    45	  /** Max spend per calendar day, in micros. */
    46	  dailyCeilingMicros: number;
    47	  /** Hard cap over the line item's lifetime, in micros. */
    48	  lifetimeCeilingMicros: number;
    49	  currency: string;
    50	  label?: string;
    51	}
    52	
    53	/**
    54	 * Tenant-level policy. All ceilings are in micros (1/1,000,000 of a unit).
    55	 * Defaults are chosen to be strict enough to be useful and loose enough
    56	 * not to block a demo: one fetch must always fit inside every ceiling.
    57	 */
    58	export interface BudgetPolicy {
    59	  /** Absolute cap per fetch, in micros. Default 10_000 (0.01). */
    60	  perCallCeilingMicros: number;
    61	  /** Cap per tenant per rolling hour, in micros. Default 100_000 (0.10). */
    62	  hourlyTenantCeilingMicros: number;
    63	  /** Cap per tenant per rolling day, in micros. Default 1_000_000 (1.00). */
    64	  dailyTenantCeilingMicros: number;
    65	  currency: string;
    66	  /** Line items are consulted after the per-call check; a fetch can fit
    67	   * the per-call rule but still exceed the line-item rule. */
    68	  lineItems: LineItem[];
    69	}
    70	
    71	export const defaultPolicy: BudgetPolicy = Object.freeze({
    72	  perCallCeilingMicros: 10_000,
    73	  hourlyTenantCeilingMicros: 100_000,
    74	  dailyTenantCeilingMicros: 1_000_000,
    75	  currency: 'USD',
    76	  lineItems: [],
    77	});
    78	
    79	export function matchLineItem(policy: BudgetPolicy, url: UrlString): LineItem | undefined {
    80	  const u = new URL(url);
    81	  const haystack = u.host + u.pathname;
    82	  return policy.lineItems.find((li) => globMatch(li.match, haystack) ?? false);
    83	}
    84	
    85	/** A very small glob: `*` matches any run of chars. Sufficient for the
    86	 *  line-item matcher; not a general-purpose path matcher on purpose. */
    87	export function globMatch(pattern: string, haystack: string): boolean {
    88	  const re = new RegExp(
    89	    '^' +
    90	      pattern
    91	        .split('*')
    92	        .map((part) => {
    93	          const hasApex = part.startsWith('.');
    94	          const escPart = (hasApex ? part.slice(1) : part).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    95	          return hasApex ? '(?:\\.?)?' + escPart : escPart;
    96	        })
    97	        .join('.*') +
    98	      '$'
    99	  );
   100	  return re.test(haystack);
   101	}"}

{"path": "packages/rails/src/rails.ts", "start_line": 1, "end_line": 224, "total_lines": 224, "content": "     1	import {
     2	  RailError,
     3	  makeSettlementRef,
     4	  type Clock,
     5	  type PaymentRail,
     6	  type PaymentRequest,
     7	  type Quote,
     8	  type RailAuthorization,
     9	  type RailSettlement,
    10	  type Micros,
    11	} from '@mwb/core';
    12	
    13	/**
    14	 * A rail is a backend: quote → authorize → settle, all behind one
    15	 * interface. Field names inside `payload` are intentionally opaque — the
    16	 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
    17	 * finalized), so the broker never parses them. Draft-caveat discipline:
    18	 * build against the interface, not a draft's field names.
    19	 */
    20	export interface RailBackend extends PaymentRail {}
    21	
    22	/**
    23	 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
    24	 * (micro-unit price, `X-PAYMENT` header) without an external service.
    25	 * Deterministic: with a `frozenClock` and fixed input, the settlement
    26	 * reference is stable so reconciliation can be asserted.
    27	 */
    28	export class InMemoryRail implements PaymentRail {
    29	  readonly id: string;
    30	  readonly priceMicros: Micros;
    31	  readonly currency: string;
    32	  readonly clock: Clock;
    33	  private readonly settlementSeed: string = '';
    34	  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';
    35	
    36	  constructor(options: {
    37	    id: string;
    38	    priceMicros: Micros;
    39	    currency?: string;
    40	    clock?: Clock;
    41	    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    42	    /** Stable suffix seed so settlement refs are deterministic in tests. */
    43	    settlementSeed?: string;
    44	  }) {
    45	    this.id = options.id;
    46	    this.priceMicros = options.priceMicros;
    47	    this.currency = options.currency ?? 'USD';
    48	    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    49	    this.failureMode = options.failureMode ?? 'none';
    50	    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
    51	  }
    52	
    53	  quote(_req: PaymentRequest): Promise<Quote> {
    54	    if (this.failureMode === 'quote') {
    55	      return Promise.reject(
    56	        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
    57	      );
    58	    }
    59	    const nowMs = Date.parse(this.clock.now());
    60	    return Promise.resolve({
    61	      unitsMicros: this.priceMicros,
    62	      currency: this.currency,
    63	      rail: this.id,
    64	      settlement: 'immediate',
    65	      expiresAt: new Date(nowMs + 60_000).toISOString(),
    66	    });
    67	  }
    68	
    69	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    70	    if (this.failureMode === 'authorize') {
    71	      return Promise.reject(
    72	        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
    73	      );
    74	    }
    75	    const payload = JSON.stringify({
    76	      schema: 'urn:rail:' + this.id,
    77	      amountMicros: quote.unitsMicros,
    78	      currency: quote.currency,
    79	      url: String(req.url),
    80	      method: req.method,
    81	    });
    82	    return Promise.resolve({
    83	      scheme: this.id,
    84	      payload,
    85	      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    86	    });
    87	  }
    88	
    89	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    90	    if (this.failureMode === 'settle') {
    91	      return Promise.reject(
    92	        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
    93	      );
    94	    }
    95	    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    96	    return Promise.resolve({
    97	      rail: this.id,
    98	      // Deterministic from (seed, url) so tests can assert reconciliation.
    99	      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
   100	      amountMicros: parsed.amountMicros,
   101	      currency: parsed.currency,
   102	      settledAt: this.clock.now(),
   103	    });
   104	  }
   105	}
   106	
   107	/** Self-hosted 402 rail: same interface, different origin. */
   108	export class SelfHosted402Rail extends InMemoryRail {
   109	  constructor(options: { priceMicros: Micros; clock?: Clock; tenantId?: string }) {
   110	    super({
   111	      id: 'self402',
   112	      priceMicros: options.priceMicros,
   113	      clock: options.clock,
   114	      settlementSeed: `self402-${options.tenantId ?? 'tenant'}`,
   115	    });
   116	    this._tenantId = options.tenantId;
   117	  }
   118	  private _tenantId?: string;
   119	  tenantId(): string | undefined {
   120	    return this._tenantId;
   121	  }
   122	}
   123	
   124	/**
   125	 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
   126	 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
   127	 * only this minimal shape — it does not depend on the bridge's own types.
   128	 * That is the "one contract" boundary in practice.
   129	 */
   130	export interface BridgeClientShape {
   131	  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
   132	  authorize(input: {
   133	    url: string;
   134	    method: string;
   135	    headers: Record<string, string>;
   136	    quote: { unitsMicros: number; currency: string };
   137	  }): Promise<RailAuthorization>;
   138	  settle(input: {
   139	    url: string;
   140	    method: string;
