   288	/**
   289	 * Create (but do not start) the HTTP server. Exposed so the test can bind an
   290	 * ephemeral port without opening a real socket in the module.
   291	 */
   292	export function createApp(cfg: ServerConfig): Server {
   293	  const { ledger, origin, originTarget, broker } = cfg;
   294	
   295	  const server = createServer((req, res) => {
   296	    const url = req.url ?? '/';
   297	    const method = req.method ?? 'GET';
   298	
   299	    if (method === 'GET' && url === '/health') {
   300	      const { status, body } = handleHealth();
   301	      return void sendJson(res, status, body);
   302	    }
   303	    if (method === 'GET' && url === '/') {
   304	      const { status, body } = handleIndex();
   305	      return void sendJson(res, status, body);
   306	    }
   307	    if (method === 'GET' && url === '/audit/dashboard') {
   308	      const { status, body } = handleAuditDashboard(ledger);
   309	      return void sendJson(res, status, body);
   310	    }
   311	    if (method === 'GET' && url === '/audit') {
   312	      const { status, body } = handleAudit(ledger);
   313	      return void sendJson(res, status, body);
   314	    }
   315	    if (method === 'POST' && url === '/fetch') {
   316	      void (async () => {
