   334	      body: {
   335	        error: 'not found',
   336	        path: url,
   337	        endpoints: ['/', '/health', '/fetch', '/audit', '/audit/dashboard'],
   338	      },
   339	    };
   340	    return void sendJson(res, status, body);
   341	  });
