   343	  // Log the effective origin mode (self-origin or proxied) at boot.
   344	  server.on('listening', () => {
   345	    // eslint-disable-next-line no-console
   346	    console.log(
   347	      `metered-web-broker listening on http://${HOST}:${PORT}` +
   348	        (originTarget ? `  (origin → ${originTarget})` : '  (self origin)'),
   349	    );
   350	  });
   351	
   352	  return server;
   353	}
   354	
   355	/** Start the HTTP server from env and listen. */
   356	export function start(): Server {
