{"path": "packages/identity/src/ring.ts", "start_line": 1, "end_line": 358, "total_lines": 358, "content": "     1	import { createPrivateKey, createPublicKey, generateKeyPairSync, sign, verify } from 'node:crypto';
     2	import { IdentityError, systemClock } from '@mwb/core';
     3	import type { Clock, HeaderRecord } from '@mwb/core';
     4	
     5	/**
     6	 * Identity & Attestation — Ed25519 key lifecycle as a first-class concern.
     7	 *
     8	 *  - issue: mint a keypair with tight expiry (default 1h, hard cap 24h)
     9	 *  - rotate: mark the current key revoked, mint the next — old key stays
    10	 *    verifiable for in-flight settlements
    11	 *  - sign: http-message-signatures style signature over selected headers
    12	 *  - PACT: broker-issued attestation token the origin can verify against
    13	 *    the public directory
    14	 *
    15	 * The directory payload below is what the broker serves at
    16	 * `/.well-known/agent-identity` so origins can look up the public key
    17	 * without a side channel.
    18	 *
    19	 * Draft-caveat discipline: build against the *patterns* of Web Bot Auth
    20	 * and PACT, not their draft field names.
    21	 */
    22	
    23	export type B64Url = string;
    24	
    25	/**
    26	 * A minimal JSON Web Key shape for an OKP / Ed25519 key. The broker never
    27	 * needs the full JWK surface — only the fields it round-trips through
    28	 * Node's `crypto` (which declares its own `JsonWebKey` under `NodeJS`, so it
    29	 * is not a global under the no-DOM base config). Declared locally to keep the
    30	 * runtime footprint honest: no DOM lib required.
    31	 */
    32	export interface OkpJwk {
    33	  kty: 'OKP';
    34	  crv: 'Ed25519';
    35	  x?: string;
    36	  d?: string;
    37	  // crypto's JsonWebKeyInput carries an index signature; keep one so the
    38	  // object literal is structurally assignable without widening the real fields.
    39	  [key: string]: unknown;
    40	}
    41	
    42	export function b64url(bytes: Uint8Array): B64Url {
    43	  return Buffer.from(bytes).toString('base64url');
    44	}
    45	
    46	export function fromB64url(s: B64Url): Uint8Array {
    47	  return new Uint8Array(Buffer.from(s, 'base64url'));
    48	}
    49	
    50	export interface KeyPair {
    51	  /** Broker-chosen stable key id — this is what the audit trail references. */
    52	  keyId: string;
    53	  algorithm: 'ed25519';
    54	  /** 32-byte public key (JWK `x`), base64url. */
    55	  publicRaw: B64Url;
    56	  /** 32-byte seed (JWK `d`), base64url. Never leaves the broker. */
    57	  privateRaw: B64Url;
    58	  createdAt: string;
    59	  expiresAt: string;
    60	  revokedAt?: string;
    61	}
    62	
    63	export interface IssueOptions {
    64	  keyId?: string;
    65	  /** Lifetime. Default 1h; hard cap 24h (tight-expiry discipline). */
    66	  ttlMs?: number;
    67	}
    68	
    69	const MAX_TTL_MS = 24 * 3_600_000;
    70	const DEFAULT_TTL_MS = 3_600_000;
    71	
    72	/**
    73	 * The broker's identity vault. Every key the broker has ever issued, in
    74	 * memory. Keys past `expiresAt` or with `revokedAt` set refuse to sign;
    75	 * the ring keeps them so in-flight signatures still verify.
    76	 */
    77	export class KeyRing {
    78	  readonly clock: Clock;
    79	  private readonly keys = new Map<string, KeyPair>();
    80	  private counter = 0;
    81	
    82	  constructor(clock: Clock = systemClock) {
    83	    this.clock = clock;
    84	  }
    85	
    86	  /** Mint a fresh Ed25519 keypair with tight expiry. */
    87	  issue(options: IssueOptions = {}): KeyPair {
    88	    const now = this.clock.now();
    89	    const nowMs = Date.parse(now);
    90	    const ttl = Math.min(Math.max(1_000, options.ttlMs ?? DEFAULT_TTL_MS), MAX_TTL_MS);
    91	    const { publicKey, privateKey } = generateKeyPairSync('ed25519');
    92	    const pubJwk = publicKey.export({ format: 'jwk' }) as OkpJwk;
    93	    const privJwk = privateKey.export({ format: 'jwk' }) as OkpJwk;
    94	    if (!pubJwk.x || !privJwk.d) {
    95	      throw new IdentityError('failed to export Ed25519 JWK', 'IDENTITY_EXPORT');
    96	    }
    97	    this.counter += 1;
    98	    const keyId = options.keyId ?? `key_${this.counter.toString(36)}_${nowMs.toString(36)}`;
    99	    if (this.keys.has(keyId)) {
   100	      throw new IdentityError(`keyId already in use: ${keyId}`, 'IDENTITY_DUPLICATE');
   101	    }
   102	    const kp: KeyPair = {
   103	      keyId,
   104	      algorithm: 'ed25519',
   105	      publicRaw: b64url(fromB64url(pubJwk.x as string)),
   106	      privateRaw: b64url(fromB64url(privJwk.d as string)),
   107	      createdAt: now,
   108	      expiresAt: new Date(nowMs + ttl).toISOString(),
   109	    };
   110	    this.keys.set(keyId, kp);
   111	    return kp;
   112	  }
   113	
   114	  /**
   115	   * Rotate: mark the current active key revoked, mint a fresh one. The old
   116	   * key remains verifiable until the caller drops it — that is what lets
   117	   * in-flight settlements close out cleanly.
   118	   */
   119	  rotate(options: IssueOptions = {}): { previous?: KeyPair; next: KeyPair } {
   120	    const current = this.active().sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
   121	    if (current) current.revokedAt = this.clock.now();
   122	    const next = this.issue(options);
   123	    return { previous: current, next };
   124	  }
   125	
   126	  get(keyId: string): KeyPair {
   127	    const kp = this.keys.get(keyId);
   128	    if (!kp) throw new IdentityError(`unknown key: ${keyId}`, 'IDENTITY_UNKNOWN');
   129	    return kp;
   130	  }
   131	
   132	  all(): KeyPair[] {
   133	    return [...this.keys.values()];
   134	  }
   135	
   136	  active(): KeyPair[] {
   137	    const now = Date.parse(this.clock.now());
   138	    return this.all().filter((k) => !k.revokedAt && Date.parse(k.expiresAt) >= now);
   139	  }
   140	
   141	  /**
   142	   * Sign a canonicalized header block.
   143	   *
   144	   * Canonicalization: lowercase header names, lexicographic order, one
   145	   * `name: value` per line, joined with `\n`, trailing `\n`. This is the
   146	   * *pattern* of http-message-signatures; the exact wire form tracks
   147	   * whatever draft the origin validates against.
   148	   *
   149	   * Returns:
   150	   *  - `signature`: the wire header value to attach
   151	   *  - `message`: the canonical signing string (for replay/debug)
   152	   *  - `signedAt`: broker timestamp
   153	   */
   154	  sign(
   155	    keyId: string,
   156	    headers: HeaderRecord,
   157	    signedFields: string[] = ['host', 'date']
   158	  ): { signature: string; message: string; signedAt: string } {
   159	    const kp = this.get(keyId);
   160	    const now = this.clock.now();
   161	    if (kp.revokedAt) throw new IdentityError(`key revoked: ${keyId}`, 'IDENTITY_REVOKED');
   162	    if (Date.parse(kp.expiresAt) < Date.parse(now)) {
   163	      throw new IdentityError(`key expired: ${keyId}`, 'IDENTITY_EXPIRED');
   164	    }
   165	
   166	    const fields = signedFields.map((f) => f.toLowerCase()).sort();
   167	    const normed = normHeaders(headers);
   168	    const lines = fields.map((f) => {
   169	      const v = normed.get(f);
   170	      if (v === undefined) throw new IdentityError(`missing header to sign: ${f}`, 'IDENTITY_FIELD');
   171	      return `${f}: ${v}`;
   172	    });
   173	    const message = lines.join('\n') + '\n';
   174	
   175	    const seed = fromB64url(kp.privateRaw);
   176	    const keyObject = createPrivateKey({
   177	      key: {
   178	        kty: 'OKP',
   179	        crv: 'Ed25519',
   180	        d: kp.privateRaw,
   181	        x: kp.publicRaw,
   182	      } as OkpJwk,
   183	      format: 'jwk',
   184	    });
   185	    const sigBytes = Buffer.from(sign(null, Buffer.from(message, 'utf8'), keyObject));
   186	    const sig = b64url(new Uint8Array(sigBytes));
   187	    const signature = `keyId="${keyId}";algorithm="ed25519";fields="${fields.join(' ')}";signature="${sig}"`;
   188	    return { signature, message, signedAt: now };
   189	  }
   190	
   191	  /** Verify a signature produced by this ring. */
   192	  verify(keyId: string, message: string, sigB64url: B64Url): boolean {
   193	    try {
   194	      const kp = this.get(keyId);
   195	      const keyObject = createPublicKey({
   196	        key: {
   197	          kty: 'OKP',
   198	          crv: 'Ed25519',
   199	          x: kp.publicRaw,
   200	        } as OkpJwk,
   201	        format: 'jwk',
   202	      });
   203	      return verify(null, Buffer.from(message, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
   204	    } catch {
   205	      return false;
   206	    }
   207	  }
   208	
   209	  /**
   210	   * Directory the broker serves at `/.well-known/agent-identity`. Only
   211	   * active keys appear, sorted by keyId for stable diffs.
   212	   */
   213	  directory(): {
   214	    format: 'agent-identity-directory';
   215	    agentIdentity: Array<{ keyId: string; alg: 'Ed25519'; pubkey: string; expires: string }>;
   216	  } {
   217	    return {
   218	      format: 'agent-identity-directory',
   219	      agentIdentity: this.active()
   220	        .slice()
   221	        .sort((a, b) => a.keyId.localeCompare(b.keyId))
   222	        .map((k) => ({
   223	          keyId: k.keyId,
   224	          alg: 'Ed25519' as const,
   225	          pubkey: k.publicRaw,
   226	          expires: k.expiresAt,
   227	        })),
   228	    };
   229	  }
   230	}
   231	
   232	function normHeaders(headers: HeaderRecord): Map<string, string> {
   233	  const out = new Map<string, string>();
   234	  for (const [k, v] of Object.entries(headers ?? {})) out.set(k.toLowerCase(), v);
   235	  return out;
   236	}
   237	
   238	/**
   239	 * A PACT is a broker-issued, key-signed attestation token. Wire format is
   240	 * intentionally minimal:
   241	 *
   242	 *   <base64url(json of claims)> . <keyId> . <base64url(signature)>
   243	 *
   244	 * where the signature covers `<claimsBytes>` exactly (so origin replays
   245	 * the same bytes it received, and the keyId selects the ring entry). When
   246	 * the PACT spec stabilizes, this token shape stays — only the payload
   247	 * inside changes.
   248	 */
   249	export class PACT {
   250	  static issue(ring: KeyRing, keyId: string, claims: Record<string, unknown>): {
   251	    token: string;
   252	    message: string;
   253	    signedAt: string;
   254	  } {
   255	    const body = JSON.stringify(claims);
   256	    const b64 = Buffer.from(body, 'utf8').toString('base64url');
   257	    const sigB64url = b64url(signPactBody(body, ring, keyId));
   258	    return {
   259	      token: `${b64}.${keyId}.${sigB64url}`,
   260	      message: body,
   261	      signedAt: ring.clock.now(),
   262	    };
   263	  }
   264	
   265	  static parse(token: string): { claims: Record<string, unknown>; keyId: string; signature: B64Url; body: string } {
   266	    const parts = token.split('.');
   267	    if (parts.length !== 3) throw new IdentityError('malformed PACT token (expected 3 parts)', 'PACT_MALFORMED');
   268	    const [bodyB64, keyId, signature] = parts as [B64Url, string, B64Url];
   269	    const body = Buffer.from(bodyB64, 'base64url').toString('utf8');
   270	    let claims: Record<string, unknown>;
   271	    try {
   272	      claims = JSON.parse(body) as Record<string, unknown>;
   273	    } catch (cause) {
   274	      throw new IdentityError('PACT claims are not valid JSON', 'PACT_CLAIMS', cause);
   275	    }
   276	    return { claims, keyId, signature, body };
   277	  }
   278	
   279	  static verify(token: string, ring: KeyRing): { valid: boolean; reason?: string; claims?: Record<string, unknown> } {
   280	    const { claims, keyId, signature, body } = PACT.parse(token);
   281	    if (new Date(claims.exp as string).getTime() < Date.parse(ring.clock.now())) {
   282	      return { valid: false, reason: 'pact-expired', claims };
   283	    }
   284	    const ok = signPactVerify(body, ring, keyId, signature);
   285	    if (!ok) return { valid: false, reason: 'signature-mismatch', claims };
   286	    return { valid: true, claims };
   287	  }
   288	}
   289	
   290	/** Sign the exact bytes of a PACT body (not a header canonicalization). */
   291	function signPactBody(body: string, ring: KeyRing, keyId: string): Uint8Array {
   292	  const kp = ring.get(keyId);
   293	  const keyObject = createPrivateKey({
   294	    key: {
   295	      kty: 'OKP',
   296	      crv: 'Ed25519',
   297	      d: kp.privateRaw,
   298	      x: kp.publicRaw,
   299	    } as OkpJwk,
   300	    format: 'jwk',
   301	  });
   302	  return new Uint8Array(sign(null, Buffer.from(body, 'utf8'), keyObject));
   303	}
   304	
   305	function signPactVerify(body: string, ring: KeyRing, keyId: string, sigB64url: B64Url): boolean {
   306	  try {
   307	    const kp = ring.get(keyId);
   308	    const keyObject = createPublicKey({
   309	      key: {
   310	        kty: 'OKP',
   311	        crv: 'Ed25519',
   312	        x: kp.publicRaw,
   313	      } as OkpJwk,
   314	      format: 'jwk',
   315	    });
   316	    return verify(null, Buffer.from(body, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
   317	  } catch {
   318	    return false;
   319	  }
   320	}
   321	
   322	// PACT helpers — small indirections so KeyRing stays readable. The `keyId`
   323	// is already on the ring, so these resolve via the ring.
   324	function require_ring_sign(_ring: KeyRing): { signature: string } {
   325	  return { signature: '' };
   326	}
   327	
   328	function signMessage(keyId: string, message: string, ring: KeyRing): { signature: B64Url } {
   329	  const kp = ring.get(keyId);
   330	  const keyObject = createPrivateKey({
   331	    key: {
   332	      kty: 'OKP',
   333	      crv: 'Ed25519',
   334	      d: kp.privateRaw,
   335	      x: kp.publicRaw,
   336	    } as OkpJwk,
   337	    format: 'jwk',
   338	  });
   339	  return { signature: b64url(new Uint8Array(sign(null, Buffer.from(message, 'utf8'), keyObject))) };
   340	}
   341	
   342	/** Convenience: issue a common-claims PACT with standard expiry. */
   343	export function issuePact(
   344	  ring: KeyRing,
   345	  keyId: string,
   346	  subject: string,
   347	  grants?: Array<{ domain?: string; scope?: string; spendCeilingMicros?: number }>
   348	): { token: string; message: string; signedAt: string } {
   349	  const nowMs = Date.parse(ring.clock.now());
   350	  const body = {
   351	    subject,
   352	    grants: grants ?? [],
   353	    iat: new Date(nowMs).toISOString(),
   354	    exp: new Date(Math.min(nowMs + 15 * 60_000, Date.parse(ring.get(keyId).expiresAt))).toISOString(),
   355	    iss: 'metered-web-broker',
   356	  };
   357	  return PACT.issue(ring, keyId, body);
   358	}"}

{"path": "packages/core/src/time.ts", "start_line": 1, "end_line": 26, "total_lines": 26, "content": "     1	/** Injectable clock + id for deterministic tests and audit replay. */
     2	export interface Clock {
     3	  now(): string;
     4	}
     5	
     6	export const systemClock: Clock = {
     7	  now(): string {
     8	    return new Date().toISOString();
     9	  },
    10	};
    11	
    12	export const frozenClock = (t = '2026-08-18T00:00:00.000Z'): Clock => ({ now: () => t });
    13	
    14	/** Random fetch ids (rfc9562-style ULID would be a drop-in upgrade). */
    15	export function makeFetchId(rand: () => number = Math.random): string {
    16	  const alphabet = '0123456789';
    17	  let id = '';
    18	  for (let i = 0; i < 16; i++) id += alphabet[Math.floor(rand() * 16) % 10]!;
    19	  return `fetch_${id}`;
    20	}
    21	
    22	export function makeSettlementRef(rail: string, rand: () => number = Math.random): string {
    23	  let suffix = '';
    24	  for (let i = 0; i < 12; i++) suffix += 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(rand() * 36)]!;
    25	  return `settle_${rail}_${suffix}`;
    26	}"}

{"path": "scripts/demo.ts", "start_line": 1, "end_line": 227, "total_lines": 227, "content": "     1	/**
     2	 * A runnable end-to-end demo of the Metered Web Broker.
     3	 *
     4	 * It exercises all four terminal outcomes against the in-memory rail, with
     5	 * a frozen clock and an injected origin client, so it is fully deterministic
     6	 * and needs no network:
     7	 *
     8	 *   1. fulfilled   — a paid fetch, receipt + obligations from a Link header
     9	 *   2. blocked     — budget ceiling exceeded (the first deny-gate)
    10	 *   3. payment-required — origin still demands payment after settlement (402)
    11	 *   4. token-rejected — origin rejects the presented identity (403 + ring)
    12	 *
    13	 * After each, the single audit ledger is rendered so the terminal decision is
    14	 * visible on the audit surface.
    15	 *
    16	 *   npm run demo   (== tsx scripts/demo.ts)
    17	 */
    18	
    19	import { frozenClock, formatMicros } from '@mwb/core';
    20	import { Broker } from '@mwb/gateway';
    21	import { BudgetEngine, defaultPolicy } from '@mwb/budget';
    22	import { AuditLedger, renderDashboard } from '@mwb/audit';
    23	import { KeyRing, PACT } from '@mwb/identity';
    24	import { InMemoryRail } from '@mwb/rails';
    25	
    26	const clock = frozenClock();
    27	
    28	const URL = 'https://api.example.com/wire/42';
    29	
    30	/** A configurable-injection OriginClient: returns whatever response we build. */
    31	function originClient(response: {
    32	  httpStatus: number;
    33	  headers?: Record<string, string>;
    34	  body?: string;
    35	}) {
    36	  return {
    37	    fetch: async () => ({
    38	      httpStatus: response.httpStatus,
    39	      headers: response.headers ?? {},
    40	      body: response.body ?? '<html>ok</html>',
    41	    }),
    42	  };
    43	}
    44	
    45	/** The L1000/2GB RSL Link header an origin publishes on a fulfilled fetch. */
    46	const LICENSE_LINK =
    47	  '<https://licenses.example/r/73>; rel="type:license-terms"; type="application/vnd.example.l1000+json"';
    48	
    49	/** Build a broker wired with a frozen clock and an injected origin. */
    50	function makeBroker(args: {
    51	  rail: ReturnType<typeof inMemory>;
    52	  budget: BudgetEngine;
    53	  ledger: AuditLedger;
    54	  ring?: KeyRing;
    55	  subject?: string;
    56	  resp: { httpStatus: number; headers?: Record<string, string>; body?: string };
    57	}) {
    58	  const { rail, budget, ledger, resp, subject } = args;
    59	  const options: ConstructorParameters<typeof Broker>[0] = {
    60	    rail,
    61	    budget,
    62	    ledger,
    63	    origin: originClient(resp),
    64	    clock,
    65	  };
    66	  if (args.ring) options.ring = args.ring;
    67	  if (subject) options.identity = { subject };
    68	  return new Broker(options);
    69	}
    70	
    71	/** A rail that "succeeds" (quote/authorize/settle all pass). */
    72	function inMemory(priceMicros: number) {
    73	  return new InMemoryRail({
    74	    id: 'x402',
    75	    priceMicros,
    76	    currency: defaultPolicy.currency,
    77	    clock,
    78	    settlementSeed: 'demo-seed',
    79	  });
    80	}
    81	
    82	/** A rail that fails settlement. */
    83	function failingRail() {
    84	  return new InMemoryRail({
    85	    id: 'x402',
    86	    priceMicros: 5000,
    87	    currency: defaultPolicy.currency,
    88	    clock,
    89	    settlementSeed: 'demo-seed',
    90	    failureMode: 'settle',
    91	  });
    92	}
    93	
    94	let seq = 0;
    95	function nextFetchId(): string {
    96	  seq += 1;
    97	  return `demo-fetch-${seq}`;
    98	}
    99	
   100	/** Print a terminal outcome's key fields as a short receipt. */
   101	function printOutcome(outcome: Awaited<ReturnType<Broker['fetch']>>, label: string): void {
   102	  console.log(`\n── ${label} ─────────────────────────────────`);
   103	  console.log(`  status    : ${outcome.status}`);
   104	  if (outcome.failureClass) console.log(`  failure   : ${outcome.failureClass}`);
   105	  if (outcome.error) console.log(`  reason    : ${outcome.error.message}`);
   106	  if (outcome.status === 'fulfilled') {
   107	    console.log(`  content   : ${outcome.content?.body}`);
   108	    console.log(`  price     : ${formatMicros(outcome.price?.unitsMicros ?? 0, outcome.price?.currency)}`);
   109	    console.log(`  settlement: ${outcome.settlementRef}`);
   110	    if (outcome.identity) {
   111	      console.log(`  identity  : keyId=${outcome.identity.keyId}`);
   112	      if (outcome.identity.pactToken) console.log(`  pactToken : [${outcome.identity.pactToken.length} chars, PACT-issued]`);
   113	    }
   114	    if (outcome.license) console.log(`  license   : id=${outcome.license.id} (rawSource=${outcome.license.rawSource})`);
   115	    if (outcome.obligations) {
   116	      console.log(`  obligations:`);
   117	      for (const o of outcome.obligations) console.log(`    - ${o.clause} → ${o.kind}: ${o.instruction}`);
   118	    }
   119	  }
   120	}
