/**
 * A minimal, dependency-free HTTP layer over a `SettlementServer`. The handler
 * receives a decoded request and returns a status + JSON body, so it can be
 * mounted on any `http.Server` (tests bind it to a `listen(0)` socket; the
 * standalone service attaches it to a real port). This keeps the routing logic
 * testable without opening a socket.
 */
type Handle = (
  req: Decoded,
): Promise<{ status: number; body: unknown }> | { status: number; body: unknown };

class RouteTable {
  private readonly routes: {
    method: 'GET' | 'POST';
    pattern: RegExp;
    handle: Handle;
  }[] = [];

  /** Register a route, matching an exact pathname against a regex. */
  add(method: 'GET' | 'POST', pattern: RegExp, handle: Handle): void {
    this.routes.push({ method, pattern, handle });
  }

  /**
   * Decode + match an incoming request. `raw` is the request body string; it is
   * only parsed when a matched handler asks for it.
   */
  async dispatch(
    method: 'GET' | 'POST',
    pathname: string,
    raw: string,
  ): Promise<{ status: number; body: unknown }> {
    const decoded: Decoded = {
      pathname,
      body: method === 'POST' ? decodeBody(raw) : undefined,
    };
    for (const r of this.routes) {
      if (r.method !== method || !r.pattern.test(pathname)) continue;
      return r.handle(decoded);
    }
    return {
      status: 404,
      body: {
        error: 'not-found',
        detail: `${method} ${pathname} does not match any settlement route`,
      },
    };
  }
}

function decodeBody(raw: string): unknown {
  if (!raw || raw.trim().length === 0) return {};
  return JSON.parse(raw) as unknown;
}
