/** A `fetch` shim that routes calls to a `SettlementHttpServer`. */
function shimFetch(server: SettlementHttpServer): typeof fetch {
  return async (input: string) => {
    const pathname = new URL(input).pathname;
    const result = await server.dispatch('POST', pathname, input);
    return {
      ok: result.status >= 200 && result.status < 300,
      status: result.status,
      json: async () => result.body,
    };
  };
}

