    // Replace global fetch for the duration of this test.
    const orig = globalThis.fetch;
    globalThis.fetch = shimFetch(http);
    try {
      const client = {
        settle: async (m: unknown) => {
          const res = await 'http://settlement.local/settle' as unknown;
          void res;
          return undefined;
        },
      };
      void client;
      // The rail commits through HttpSettlementClient, which uses global fetch.
      const rail = new SelfHosted402Rail(
        {
          keyId: key.keyId,
          isValidMandate: () => true,
          settle: async (m: unknown) => {
            const res = await http.dispatch('POST', '/settle', JSON.stringify(m));
            if (res.status !== 200) {
              throw new RailError('settlement failed', 'RAIL_SETTLE', undefined, false);
            }
            const b = res.body as { rail: string; settlementRef: string; amountMicros: number; currency: string; settledAt: string };
            return {
              rail: b.rail,
              settlementRef: b.settlementRef,
              amountMicros: b.amountMicros,
              currency: b.currency,
              settledAt: b.settledAt,
            };
          },
        },
        key,
        { priceMicros: 5000, clock, origin: REQ.url },
      );
      const quote = await rail.quote(REQ);
      const auth = await rail.authorize(REQ, quote);
      const s = await rail.settle(REQ, auth);
      expect(s.settlementRef).toMatch(/^settle_self402_/);
      expect(server.settledCount()).toBe(1);
    } finally {
      globalThis.fetch = orig;
    }
  });
